/**
 * generated by stackra gen from src/routes/offline/offline.route.ts (`prerender: true`),
 * src/config/i18n.config.ts and src/styles/app.css — do not edit
 * Purpose: the hydration entry of the prerendered offline pages: one small bundle, precached with
 *          them, that brings the static page of each locale to life (the connection state, the
 *          queue count, the retry) without the app shell, which is exactly what is missing when
 *          the worker serves this page.
 * Boundary: hydrates `OfflineRoute` inside `PublicLayout` only: no router over the whole tree, no
 *           session, no generated client. The locale is the one the page was prerendered for
 *           (read from `<html lang>`), so the strings are already in the HTML and only the
 *           device-side contexts (platform, query queue, theming, i18n) are mounted. A page
 *           without `#root` is a broken build, so it fails loudly.
 * Runtime: browser
 */
import "#src/styles/app.css";
import { hydrateRoute } from "@stackra/app/browser";
import { wiring } from "#stackra/wiring";
import { PublicLayout } from "#src/routes/public/public.layout";
import { Public } from "#src/routes/public/public";
import { OfflineRoute } from "#src/routes/offline/offline.route";
import { Offline } from "#src/routes/offline/offline";

const root = document.getElementById("root");
if (!root) throw new Error("the offline page has no #root element; rerun `stackra build`.");

await hydrateRoute(root, {
  wiring,
  layout: { class: PublicLayout, component: Public },
  route: { class: OfflineRoute, component: Offline },
  locale: document.documentElement.lang,
  contexts: ["platform", "query", "theming", "i18n", "ui"],
});
